INSERT INTO test.dm_nganh VALUES ('A', 'Nong nghiep, lam nghiep va thuy san');
INSERT INTO test.dm_nganh VALUES ('B', 'Khai khoang');
INSERT INTO test.dm_nganh VALUES ('C1', 'Cong nghiep dien tu, may vi tinh, san pham quang hoc');
INSERT INTO test.dm_nganh VALUES ('C2', 'Cong nghiep che bien, che tao khac');
INSERT INTO test.dm_nganh VALUES ('D', 'San xuat, phan phoi dien, khi dot, nuoc nong, hoi nuoc');
INSERT INTO test.dm_nganh VALUES ('E', 'Cung cap nuoc; quan ly va xu ly rac thai, nuoc thai');
INSERT INTO test.dm_nganh VALUES ('F', 'Xay dung');
INSERT INTO test.dm_nganh VALUES ('G', 'Ban buon va ban le; sua chua o to, xe may');
INSERT INTO test.dm_nganh VALUES ('H', 'Van tai, kho bai');
INSERT INTO test.dm_nganh VALUES ('I', 'Dich vu luu tru va an uong');
INSERT INTO test.dm_nganh VALUES ('J', 'Thong tin va truyen thong');
INSERT INTO test.dm_nganh VALUES ('K', 'Hoat dong tai chinh, ngan hang va bao hiem');
INSERT INTO test.dm_nganh VALUES ('L', 'Hoat dong kinh doanh bat dong san');
INSERT INTO test.dm_nganh VALUES ('M', 'Hoat dong chuyen mon, khoa hoc va cong nghe');
INSERT INTO test.dm_nganh VALUES ('N', 'Hoat dong hanh chinh va dich vu ho tro');
INSERT INTO test.dm_nganh VALUES ('O', 'Quan ly nha nuoc, an ninh quoc phong, bao dam xa hoi');
INSERT INTO test.dm_nganh VALUES ('P', 'Giao duc va dao tao');
INSERT INTO test.dm_nganh VALUES ('Q', 'Y te va hoat dong tro giup xa hoi');
INSERT INTO test.dm_nganh VALUES ('R', 'Nghe thuat, vui choi va giai tri');
INSERT INTO test.dm_nganh VALUES ('S', 'Hoat dong dich vu khac');
INSERT INTO test.dm_nganh VALUES ('T', 'Hoat dong lam thue cong viec ho gia dinh');
INSERT INTO test.dm_nganh VALUES ('U', 'Hoat dong cua to chuc, co quan quoc te');
INSERT INTO test.dm_nghia_vu_tuan_thu VALUES (1, 'Bao cao dinh ky', 'Nop bao cao hoat dong dau tu dung han', '{DDI,FDI,ODI}', 'QUY');
