INSERT INTO test.dm_nghia_vu_tuan_thu VALUES (6, 'Nghia vu tai chinh', 'Thuc hien tai chinh on dinh', '{DDI,FDI,ODI}', 'NAM');
INSERT INTO test.dm_nghia_vu_tuan_thu VALUES (7, 'Thu tuc dang ky cap tai khoan bao cao', 'Tuan thu dang ky cap tai khoan bao cao', '{DDI,FDI,ODI}', 'NAM');
INSERT INTO test.dm_nghia_vu_tuan_thu VALUES (8, 'Quy dinh phap luat', 'Tuan thu quy dinh phap luat ve moi truong, xay dung va cac quy dinh khac', '{DDI,FDI,ODI}', 'NAM');
